search = func(a [34]int, sets []Block) {
	if a[first] >= 3 {
		a[first] -= 3
		next := append(append([]Block(nil),
			sets...), Block{kind: first, source: "concealed"})
		search(a, next)
		a[first] += 3
	}
	if first < 27 && first%9 <= 6 && a[first+1] > 0 && a[first+2] > 0 {
		a[first]--
		a[first+1]--
		a[first+2]--
		next := append(append([]Block(nil),
			sets...), Block{kind: first, sequence: true, source: "concealed"})
		search(a, next)
	}
